INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 5, 'theory', 'Quiz: aggregate functions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 0, 'A table has 10 customers, 3 of whom have no email. What is COUNT(email)?', '["10", "7", "3", "0"]', 1, 'COUNT(column) counts only non-empty values: 10 − 3 = 7. COUNT(*) would return 10.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 1, 'Column values: 10, NULL, 30. What is AVG?', '["13.33", "20", "40", "NULL"]', 1, 'NULL is skipped and is not part of the divisor: (10 + 30) / 2 = 20.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 2, 'What does SELECT SUM(total) FROM orders return if there are no matching rows at all?', '["0", "NULL", "An error", "An empty result with no rows"]', 1, 'On an empty set SUM returns NULL (and COUNT returns 0). To get 0, use COALESCE(SUM(total), 0).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 3, 'Why can''t you write WHERE SUM(total) > 1000?', '["SUM cannot be applied to numbers", "WHERE runs before aggregation, so the sum does not exist yet", "SUM must be written in capital letters", "The > sign cannot be used with SUM"]', 1, 'WHERE selects rows before the collapse. A condition on an aggregate''s value goes in HAVING.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 5, 4, 'How do you count the number of distinct cities among customers?', '["COUNT(city)", "COUNT(DISTINCT city)", "SELECT DISTINCT COUNT(city)", "SUM(DISTINCT city)"]', 1, 'COUNT(DISTINCT city) removes duplicates before counting; gaps are not counted either.');
